const query = 'restless legs syndrome treatment guideline';
const pageSize = 5;

if (!query.trim() || query.length > 500) {
  throw new Error('query must contain 1-500 characters');
}

return [{
  json: {
    schemaVersion: 1,
    jobId: `manual-${Date.now()}`,
    query: query.trim(),
    pageSize,
  },
}];

const request = $('Prepare Search').first().json;
const payload = $input.first().json;
const records = Array.isArray(payload?.resultList?.result) ? payload.resultList.result : [];
const cleanText = (value, maxLength) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, maxLength);

const results = records.slice(0, request.pageSize).map((record) => {
  const source = cleanText(record.source, 16);
  const id = cleanText(record.id || record.pmid || record.pmcid, 128);
  return {
    source,
    id,
    pmid: cleanText(record.pmid, 32),
    pmcid: cleanText(record.pmcid, 32),
    doi: cleanText(record.doi, 256),
    title: cleanText(record.title, 1000),
    authors: cleanText(record.authorString, 1000),
    journal: cleanText(record.journalTitle, 500),
    publicationYear: cleanText(record.pubYear, 8),
    publicationTypes: cleanText(record.pubType, 500),
    abstract: cleanText(record.abstractText, 4000),
    citedByCount: Number(record.citedByCount || 0),
    isOpenAccess: record.isOpenAccess === 'Y',
    url: source && id
      ? `https://europepmc.org/article/${encodeURIComponent(source)}/${encodeURIComponent(id)}`
      : '',
  };
});

return [{
  json: {
    schemaVersion: 1,
    jobId: request.jobId,
    provider: 'Europe PMC',
    query: request.query,
    retrievedAt: new Date().toISOString(),
    totalHits: Number(payload?.hitCount || 0),
    resultCount: results.length,
    results,
  },
}];
